const INDEX = new Map<string, number>(ROAD_IDS.map((id, i) => [id, i]))

/** Road distance in km between two places, or null when either isn't on the table. */
export function roadKm(from: string, to: string): number | null {
  const a = INDEX.get(from)
  const b = INDEX.get(to)
  if (a === undefined || b === undefined) return null
  return METRES[a]![b]! / 1000
}
